/// Returns true if `n` is a positive power of two.
fn is_2_pow(n: i32) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Finds the lower‐bound index `k` in the slice `a[lo..hi]` such that:
///  - for all `r` with `lo <= r < k`, `a[r] < x`
///  - for all `r` with `k <= r < hi`, `a[r] >= x`
///
/// Equivalently, this returns the insertion position of `x` into the
/// sorted range `a[lo..hi]`.
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut lo = lo;
    let mut hi = hi;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

/// Computes the lower‐bound insertion index of `x` into the first 1000
/// elements of `a`. Assumes `a.len() >= 1000` and that `a[0..1000]`
/// is sorted in nondecreasing order.
///
/// Returns an index `k` in `0..=1000` such that:
///  - for all `r < k`, `a[r] < x`
///  - for all `k <= r < 1000`, `a[r] >= x`
fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(
        a.len() >= 1000,
        "search_1000 requires the array to have at least 1000 elements"
    );
    search_range_helper(a, x, 0, 1000)
}

